// Renders the real surfaces against fixture data, so the layout can be eyeballed
// without going through the email OTP gate.
import { StrictMode, useEffect, useState } from 'react'
import { createRoot } from 'react-dom/client'
import './styles.css'

// Fixture is generated by tools/make_preview.py and gitignored: it carries real
// contact names, which must never enter the repo.
const SAMPLE = [{
  id: 'sample', title: 'Project Manager', company_raw: 'Example Co',
  location: 'New York, NY', posted_on: new Date().toISOString().slice(0, 10),
  url: '#', strength: 12.0, contacts_at_company: 2,
  contact_name: 'A Contact', contact_role: 'CEO & Founder',
  source_label: "a trusted person's network",
}]

// Feed reads from Supabase via useFeed; for preview we re-implement only the
// presentational shell and reuse the identical class names.
function heat(s) { return s == null ? 'none' : s >= 11 ? 'hot' : s >= 9 ? 'warm' : 'mild' }
function ago(d) {
  if (!d) return ''
  const days = Math.round((Date.now() - new Date(d).getTime()) / 86400000)
  return days <= 0 ? 'today' : days === 1 ? 'yesterday' : `${days}d ago`
}

function Preview() {
  const [rows, setRows] = useState(SAMPLE)
  useEffect(() => {
    fetch('./previewData.json')
      .then((r) => (r.ok ? r.json() : null))
      .then((d) => d && d.length && setRows(d))
      .catch(() => {})
  }, [])
  return (
    <div className="app">
      <header className="top">
        <h1>warm</h1>
        <nav className="views">
          <button className="view is-active">Jobs</button>
          <button className="view">Review<span className="badge">2</span></button>
          <button className="view">Import</button>
        </nav>
      </header>
      <nav className="tabs">
        {['Warm', 'All new', 'Interested', 'Applied'].map((t, i) => (
          <button key={t} className={`tab ${i === 0 ? 'is-active' : ''}`}>{t}</button>
        ))}
      </nav>
      <ul className="cards">
        {rows.map((row) => {
          const others = (row.contacts_at_company || 1) - 1
          return (
            <li key={row.id} className={`card card-${heat(row.strength)}`}>
              <div className="card-head">
                <a className="card-title" href={row.url}>{row.title}</a>
                <span className="score">{row.strength.toFixed(1)}</span>
              </div>
              <div className="card-sub">
                {row.company_raw}
                {row.location && <span className="muted"> · {row.location}</span>}
                {row.posted_on && <span className="muted"> · {ago(row.posted_on)}</span>}
              </div>
              <div className="conn">
                <span className={`dot dot-${heat(row.strength)}`} />
                <div>
                  <div className="conn-name">
                    {row.contact_name}
                    {row.contact_role && <span className="conn-role"> · {row.contact_role}</span>}
                  </div>
                  <div className="conn-meta">
                    via {row.source_label}{others > 0 && ` · +${others} more here`}
                  </div>
                </div>
              </div>
              <div className="actions">
                <button>Interested</button>
                <button>Applied</button>
                <button className="ghost">Skip</button>
              </div>
            </li>
          )
        })}
      </ul>
    </div>
  )
}

createRoot(document.getElementById('root')).render(<StrictMode><Preview /></StrictMode>)
